export default {
  file: "2026-0908-texts-tt.docx",
  date: "2026-09-08",
  key: "09-08",
  paragraphs: 616,
  blocks: [
    {"k": "heading", "p": [0, 0], "text": "SEPTEMBER 8"},
    {"k": "heading", "p": [1, 1], "text": "The Nativity of our Most Holy Lady Theotokos and Ever-Virgin Mary"},
    {"k": "heading", "p": [3, 3], "text": "\"Lord I Call...\" Tone 6"},
    {"k": "text", "p": [5, 10], "text": "Lord, I call upon Thee, [hear] me! | [Hear] me, O Lord! | Lord, I call upon Thee, [hear] me! | Receive the [voice] of my prayer, | when I [cal]l upon Thee! // Hear [me], O Lord!", "n": 6, "head": "\"Lord I Call...\" Tone 6", "pointed": true},
    {"k": "text", "p": [12, 16], "text": "Let my [prayer] arise | in Thy sight as [in]cense, | and let the lifting [up] of my hands | be an evening [sac]rifice! // Hear [me], O Lord!", "n": 5, "head": "\"Lord I Call...\" Tone 6", "pointed": true},
    {"k": "text", "p": [18, 18], "text": "V. (8) Out of the depths I cry to Thee, O Lord. Lord, hear my voice!", "n": 1, "head": "\"Lord I Call...\" Tone 6"},
    {"k": "heading", "p": [20, 20], "text": "Tone 6 Idiomela (by Patriarch Sergius)"},
    {"k": "text", "p": [22, 29], "text": "Today God, Who rests upon the [spir]itual thrones, | has prepared for Himself a holy [throne] on earth. | He Who in wisdom established the [heav]ens | has fashioned a living heaven in His [love] for mankind; | for, from a barren root He has made a life-bearing branch spring [up] for us, | even His [Moth]er. | O God of wonders and Hope of the [hope]less, // O Lord, [glo]ry to Thee!", "n": 8, "head": "Tone 6 Idiomela (by Patriarch Sergius)", "pointed": true},
    {"k": "text", "p": [31, 31], "text": "V. (7) Let Thine ears be attentive to the voice of my supplications!", "n": 1, "head": "Tone 6 Idiomela (by Patriarch Sergius)"},
    {"k": "text", "p": [34, 41], "text": "This is the [day] of the Lord! | Rejoice, O [peo]ples, | for, behold, the bridal chamber of the Light, the book of the [Word] of Life, | has come [forth] from the womb! | The gate that faces the [East] is born | and awaits the entry of the [Great] Priest. | She alone admits [Christ] into the world // for the sal[va]tion of our souls.", "n": 8, "head": "Tone 6 Idiomela (by Patriarch Sergius)", "pointed": true},
    {"k": "text", "p": [43, 43], "text": "V. (6) If Thou, O Lord, shouldst mark iniquities, Lord, who could stand? But there is forgiveness with Thee.", "n": 1, "head": "Tone 6 Idiomela (by Patriarch Sergius)"},
    {"k": "text", "p": [45, 54], "text": "Although by God’s will other barren [wom]en | have brought forth famous [off]spring, | yet, of all those children Mary shines most brightly, as is [fit]ting to God. | For she herself was born wondrously of a barren [moth]er, | and gave birth in the flesh to the [God] of all, | in a manner surpassing nature, from a womb with[out] seed. | She is the only gateway of the only-begotten [Son] of God, | Who passed through this gate yet [kept] it closed, | and, having ordered all things in His own [wis]dom, // has wrought salvation for [all] mankind.", "n": 10, "head": "Tone 6 Idiomela (by Patriarch Sergius)", "pointed": true},
    {"k": "text", "p": [56, 56], "text": "V. (5) For Thy Name’s sake I wait for Thee, O Lord. My soul has waited for Thy word; my soul has hoped on the Lord.", "n": 1, "head": "Tone 6 Idiomela (by Patriarch Sergius)"},
    {"k": "text", "p": [58, 58], "text": "(Repeat: “Although by God’s will…”)", "n": 1, "head": "Tone 6 Idiomela (by Patriarch Sergius)"},
    {"k": "text", "p": [60, 60], "text": "V. (4) From the morning watch until night, from the morning watch, let Israel hope on the Lord!", "n": 1, "head": "Tone 6 Idiomela (by Patriarch Sergius)"},
    {"k": "heading", "p": [62, 62], "text": "Tone 6 Idiomela (by Stephen of Jerusalem)"},
    {"k": "text", "p": [64, 69], "text": "Today the gates of barrenness are [o]pened, | and the virgin gate of [God] comes forth. | Today grace begins to bear its [first] fruit, | revealing to the world the [Moth]er of God[.] | Through her things on earth are joined with the [heav]ens // for the sal[va]tion of our souls.", "n": 6, "head": "Tone 6 Idiomela (by Stephen of Jerusalem)", "pointed": true},
    {"k": "text", "p": [71, 71], "text": "V. (3) For with the Lord there is mercy and with Him is plenteous redemption, and He will deliver Israel from all his iniquities.", "n": 1, "head": "Tone 6 Idiomela (by Stephen of Jerusalem)"},
    {"k": "text", "p": [73, 73], "text": "(Repeat: “Today the gates of barrenness…”)", "n": 1, "head": "Tone 6 Idiomela (by Stephen of Jerusalem)"},
    {"k": "text", "p": [75, 75], "text": "V. (2) Praise the Lord, all nations! Praise Him, all peoples!", "n": 1, "head": "Tone 6 Idiomela (by Stephen of Jerusalem)"},
    {"k": "text", "p": [77, 86], "text": "Today is the prelude of uni[ver]sal joy; | today the winds blow that herald sal[va]tion, | and the barrenness of our [na]ture is dispelled; | for the barren woman is revealed as the [moth]er | of her who remained a [vir]gin | after giving birth to the Cre[at]or. | From her the One Who is God by [na]ture | takes what is foreign to Him and [makes] it His own, | and works salvation through the flesh for those who have [gone] astray. // He is Christ, the Lover of man and the Re[deem]er of our souls.", "n": 10, "head": "Tone 6 Idiomela (by Stephen of Jerusalem)", "pointed": true},
    {"k": "text", "p": [88, 88], "text": "V. (1) For His mercy is confirmed on us, and the truth of the Lord endures forever.", "n": 1, "head": "Tone 6 Idiomela (by Stephen of Jerusalem)"},
    {"k": "text", "p": [90, 95], "text": "Today barren Anna gives birth to the [hand]maid of God, | who was chosen from all gener[at]ions | to become the abode of the King and Creator of all, [Christ] our God | in fulfillment of the di[vine] plan. | Through her we earth-born have been [fash]ioned anew // and restored from corruption to life e[ter]nal.", "n": 6, "head": "Tone 6 Idiomela (by Stephen of Jerusalem)", "pointed": true},
    {"k": "note", "p": [97, 97], "text": "Glory to the Father, and to the Son, and to the Holy Spirit;"},
    {"k": "note", "p": [98, 98], "text": "now and ever, and unto ages of ages. Amen."},
    {"k": "heading", "p": [101, 101], "text": "Tone 6 (by Patriarch Sergius)"},
    {"k": "text", "p": [103, 110], "text": "Today God, Who rests upon the [spir]itual thrones, | has prepared for Himself a holy [throne] on earth. | He Who in wisdom established the [heav]ens | has fashioned a living heaven in His [love] for mankind; | for, from a barren root He has made a life-bearing branch spring [up] for us, | even His [Moth]er. | O God of wonders and Hope of the [hope]less, // O Lord, [glo]ry to Thee!", "n": 8, "head": "Tone 6 (by Patriarch Sergius)", "pointed": true},
    {"k": "heading", "p": [112, 112], "text": "Old Testament Readings"},
    {"k": "heading", "p": [113, 113], "text": "Genesis 28:10-17"},
    {"k": "heading", "p": [114, 114], "text": "Ezekiel 43:2-44:4"},
    {"k": "heading", "p": [115, 115], "text": "Proverbs 9:1-11"},
    {"k": "heading", "p": [116, 116], "text": "Litya"},
    {"k": "heading", "p": [118, 118], "text": "Tone 1 Idiomela (by Stephen of Jerusalem)"},
    {"k": "text", "p": [120, 132], "text": "The first [fruit] of our salvation is accomplished today, O [peo]ples, | for behold, the Mother and Virgin and [ves]sel of God, | foreor[dain]ed from ancient gener[a]tions, | comes to be born from a [bar]ren [wom]an. | A [flow]er from Jesse and a rod from his root has [bud]ded; | let Adam, our forefather, be glad; let Eve re[joice] and delight, | for be[hold], she who was formed from [Ad]am’s rib | plainly declares her daughter and de[scend]ant [bless]ed: | “My de[liv]erance has been [born],” says Eve; | “through her, I shall be freed from the bonds of [Ha]des.” | Let [Da]vid rejoice, striking his lyre, and let him [bless] God, | for behold, the Virgin comes [forth] from a [bar]ren rock // for the sal[va]tion of our souls!", "n": 13, "head": "Tone 1 Idiomela (by Stephen of Jerusalem)", "pointed": true},
    {"k": "heading", "p": [134, 134], "text": "Tone 2"},
    {"k": "text", "p": [136, 141], "text": "Come, all you friends of vir[gin]ity, | and you lovers of [pu]rity, | [come], and welcome with love the boast of [vir]gins! | She is the fountain of life that flows from the [sol]id rock; | she is the bush that springs from the [bar]ren ground // and burns with the immaterial fire that cleanses and en[light]ens our souls.", "n": 6, "head": "Tone 2", "pointed": true},
    {"k": "heading", "p": [143, 143], "text": "Tone 2 (by Anatolius)"},
    {"k": "text", "p": [145, 150], "text": "What is this sound of [feast]ing we hear? | Joachim and Anna mystically celebrate, [say]ing: | “Re[joice] with us today, O [Ad]am and Eve; | for if by your transgression you closed the gate of Paradise to [those] of old, | we have now been given a [glo]rious fruit, // Mary the child of God, who opens its [en]trance to all!”", "n": 6, "head": "Tone 2 (by Anatolius)", "pointed": true},
    {"k": "text", "p": [153, 160], "text": "She who was foreordained [Queen] of all | and the habi[ta]tion of God, | has come [forth] today from the barren womb of joyful [An]na. | She is the divine sanctuary of the eternal [Es]sence; | shameless Hades has been trampled [down] through her, | and [Eve] with all her race is established se[cure] in life. | It is meet and right that we should cry a[loud] to her: // “Blessed art thou among women, and blessed is the [Fruit] of thy womb!”", "n": 8, "head": "Tone 2 (by Anatolius)", "pointed": true},
    {"k": "note", "p": [162, 162], "text": "Glory to the Father, and to the Son, and to the Holy Spirit;"},
    {"k": "note", "p": [163, 163], "text": "now and ever, and unto ages of ages. Amen."},
    {"k": "heading", "p": [165, 165], "text": "Tone 8 (by Patriarch Sergius)"},
    {"k": "text", "p": [167, 175], "text": "Let us [strike] our spiritual harp on this solemn [day] of our feast, | for today, from the seed of [Da]vid, | the Mother of Life is born, dis[pel]ling the [dark]ness. | She is the restoration of Adam, and the re[cal]ling of Eve. | She is the source of incorruption and our release from cor[rup]tion. | Through her we have been made [God]like and de[liv]ered from death. | So let us the faithful cry out to her with [Ga]briel: | “Rejoice, O full of grace, the [Lord] is with thee, // granting us His great [mer]cy through thee!”", "n": 9, "head": "Tone 8 (by Patriarch Sergius)", "pointed": true},
    {"k": "heading", "p": [177, 177], "text": "Aposticha"},
    {"k": "heading", "p": [179, 179], "text": "Tone 4 Idiomela (by Patriarch Germanus)"},
    {"k": "text", "p": [181, 186], "text": "The joy of all the world has dawned for us from the [right]eous ones: | the all-praised Virgin who springs from Joachim and [An]na. | Through the a[bun]dance of goodness she becomes the living [tem]ple of God, | and she alone is acknowledged as truly the Theo[to]kos. | Through her [prayers], O [Christ] God, // send peace to the world and to our souls great [mer]cy!", "n": 6, "head": "Tone 4 Idiomela (by Patriarch Germanus)", "pointed": true},
    {"k": "text", "p": [188, 188], "text": "V. Hearken, O daughter, and see, and incline thine ear! (Ps. 44:9a)", "n": 1, "head": "Tone 4 Idiomela (by Patriarch Germanus)"},
    {"k": "text", "p": [190, 197], "text": "As foretold by the Angel’s [proph]ecy, | thou hast come forth today, O [Vir]gin, | the most [sa]cred fruit of righteous Joachim and [An]na. | Thou art the heaven and throne of God, the vessel of [pu]rity, | heralding joy to all the world, thou that [bring]est us [our] life; | thou dost destroy the curse and givest [bless]ing in its stead. | Wherefore on this feast of thy birth, O Maiden [called] by God, // entreat peace for the world and for our souls great [mer]cy!", "n": 8, "head": "Tone 4 Idiomela (by Patriarch Germanus)", "pointed": true},
    {"k": "text", "p": [199, 199], "text": "V. Even the rich among the people shall pray before thy face. (Ps. 44:11b)", "n": 1, "head": "Tone 4 Idiomela (by Patriarch Germanus)"},
    {"k": "text", "p": [201, 215], "text": "Let the barren and childless Anna today clap her hands with [glad]ness! | Let those on earth be decked in [splen]dor; | let [rul]ers [leap] for joy; | let priests be glad in blessing; let the whole [world] keep the feast! | For behold, the Queen and immaculate [bride] of the [Fa]ther | has sprung forth from the root of [Jes]se. | No longer will women bear children in [sor]row, | for joy has [blos]somed forth, | and the Life of mankind now [dwells] in the world. | No longer are the offerings of Joachim [turned] away, | for the lamentation of Anna has been [changed] to joy. | She cries: “Rejoice with me, all you chosen of [Is]rael, | for behold, the Lord has given me the living palace of His divine [glo]ry | for our common [glad]ness and joy // and for the sal[va]tion of our souls!”", "n": 15, "head": "Tone 4 Idiomela (by Patriarch Germanus)", "pointed": true},
    {"k": "note", "p": [217, 217], "text": "Glory to the Father, and to the Son, and to the Holy Spirit;"},
    {"k": "note", "p": [218, 218], "text": "now and ever, and unto ages of ages. Amen."},
    {"k": "heading", "p": [220, 220], "text": "Tone 8 (by Patriarch Sergius)"},
    {"k": "text", "p": [222, 231], "text": "[Come], all you faithful, let us run to the [Vir]gin! | For, behold, today she is born, who was foreordained before the womb, as the [Moth]er of our God, | the treasure of virginity, the rod of Aaron that budded, springing from the [root] of [Jes]se, | the preaching of the Prophets, the offspring of righteous Joachim and [An]na. | She is born and with her the [world] is renewed. | She comes from the womb and the Church is a[dorned] in her [maj]esty. | She is the holy temple, the vessel of the [God]head, | the virgin instrument and bridal [cham]ber of the King, | in which has come to pass the strange mystery of the union of the natures that [came] to[geth]er in Christ. // Worshipping Him, we praise the birth of the all-pure [Vir]gin.", "n": 10, "head": "Tone 8 (by Patriarch Sergius)", "pointed": true},
    {"k": "heading", "p": [234, 234], "text": "Tone 4 Troparion"},
    {"k": "text", "p": [236, 242], "text": "Thy nativity, O [Vir]gin, | has proclaimed joy to the whole [u]niverse! | The Sun of righteousness, [Christ] our God, | has shone from thee, O Theo[to]kos. | By an[nul]ling the curse, | He bestowed a [bless]ing. // By destroying death, He has granted us e[ter]nal life.", "n": 7, "head": "Tone 4 Troparion", "pointed": true},
    {"k": "note", "p": [244, 244], "text": "(sung once at Great Vespers, thrice at Vigil)"},
    {"k": "heading", "p": [247, 247], "text": "(at Matins)"},
    {"k": "heading", "p": [249, 249], "text": "\"God is the Lord…\" Tone 4"},
    {"k": "heading", "p": [251, 251], "text": "Tone 4 Troparion"},
    {"k": "text", "p": [253, 259], "text": "Thy nativity, O [Vir]gin, | has proclaimed joy to the whole [u]niverse! | The Sun of righteousness, [Christ] our God, | has shone from thee, O Theo[to]kos. | By an[nul]ling the curse, | He bestowed a [bless]ing. // By destroying death, He has granted us e[ter]nal life.", "n": 7, "repeat": "thrice", "head": "Tone 4 Troparion", "pointed": true},
    {"k": "heading", "p": [261, 261], "text": "The Polyeleion"},
    {"k": "heading", "p": [263, 263], "text": "Magnification"},
    {"k": "text", "p": [265, 268], "text": "We magnify thee, | O Most-Holy Virgin | and we honor thy holy parents | and praise thine all-glorious nativity.", "n": 4, "head": "Magnification"},
    {"k": "text", "p": [270, 270], "text": "V. O Lord, remember David and all his meekness. (Ps. 131:1)", "n": 1, "head": "Magnification"},
    {"k": "text", "p": [272, 272], "text": "[V.] Arise, O Lord, into Thy rest; Thou and the Ark of Thy Holiness. (Ps. 131:8)", "n": 1, "head": "Magnification", "pointed": true},
    {"k": "note", "p": [274, 274], "text": "Glory to the Father, and to the Son, and to the Holy Spirit,"},
    {"k": "text", "p": [275, 275], "text": "now and ever, and unto ages of ages. Amen.", "n": 1, "head": "Magnification"},
    {"k": "heading", "p": [277, 277], "text": "Tone 4 Prokeimenon"},
    {"k": "text", "p": [279, 279], "text": "I will remember thy name / from generation to generation. (Ps. 44:16)", "n": 1, "head": "Tone 4 Prokeimenon"},
    {"k": "text", "p": [281, 281], "text": "V. My heart overflowed with a good word. (Ps. 44:1a)", "n": 1, "head": "Tone 4 Prokeimenon"},
    {"k": "text", "p": [283, 283], "text": "Let everything that breathes praise the Lord!", "n": 1, "head": "Tone 4 Prokeimenon"},
    {"k": "text", "p": [285, 285], "text": "V. Praise God in His sanctuary! Praise Him in His mighty firmament! (Ps. 150:1)", "n": 1, "head": "Tone 4 Prokeimenon"},
    {"k": "heading", "p": [288, 288], "text": "Gospel"},
    {"k": "text", "p": [289, 289], "text": "(4) Luke 1:39-49, 56", "n": 1, "head": "Gospel"},
    {"k": "note", "p": [291, 291], "text": "“Having beheld the Resurrection of Christ…” is not sung, but immediately Psalm 50."},
    {"k": "heading", "p": [293, 293], "text": "Tone 2 Post-Gospel Stichera"},
    {"k": "text", "p": [295, 295], "text": "Glory to the Father, and to the Son, and to the Holy [Spir]it.", "n": 1, "head": "Tone 2 Post-Gospel Stichera", "pointed": true},
    {"k": "text", "p": [297, 299], "text": "Through the prayers of the Theo[to]kos, | O [mer]ciful One, // blot out the multitude of my trans[gres]sions.", "n": 3, "head": "Tone 2 Post-Gospel Stichera", "pointed": true},
    {"k": "text", "p": [301, 301], "text": "Now and ever, and unto ages of [a]ges. Amen.", "n": 1, "head": "Tone 2 Post-Gospel Stichera", "pointed": true},
    {"k": "text", "p": [303, 305], "text": "Through the prayers of the Theo[to]kos, | O [mer]ciful One, // blot out the multitude of my trans[gres]sions.", "n": 3, "head": "Tone 2 Post-Gospel Stichera", "pointed": true},
    {"k": "heading", "p": [307, 307], "text": "Tone 6"},
    {"k": "text", "p": [309, 312], "text": "Have mercy on [me], O God, | according to Thy great [mer]cy, | and according to the multitude of Thy tender [mer]cies // blot out my trans[gress]ion.", "n": 4, "head": "Tone 6", "pointed": true},
    {"k": "heading", "p": [314, 314], "text": "Tone 6"},
    {"k": "text", "p": [316, 323], "text": "This is the [day] of the Lord! | Rejoice, O [peo]ples, | for, behold, the bridal chamber of the Light, the book of the [Word] of Life, | has come [forth] from the womb! | The gate that faces the [East] is born | and awaits the entry of the [Great] Priest. | She alone admits [Christ] into the world // for the sal[va]tion of our souls.", "n": 8, "head": "Tone 6", "pointed": true},
    {"k": "heading", "p": [326, 326], "text": "Tone 2 1st Canon, Ode 1 – Heirmos (by St. John of Damascus)"},
    {"k": "text", "p": [328, 331], "text": "Come, O peoples, let us sing a song to Christ our God | Who parted the sea and through it led His people, | whom He had brought out of bondage in Egypt; // for He has been glorified!", "n": 4, "head": "Tone 2 1st Canon, Ode 1 – Heirmos (by St. John of Damascus)"},
    {"k": "heading", "p": [333, 333], "text": "Tone 8 Katavasia, Ode 1 (from the Canon of the Elevation of the Cross,"},
    {"k": "note", "p": [334, 334], "text": "by Cosmas the monk)"},
    {"k": "text", "p": [336, 342], "text": "Moses traced out a cross, | as with his staff he divided the Red Sea in two, | so that Israel could go across on foot; | and then striking it again crosswise, | and uniting it over Pharoah and his chariots, | he inscribed the Invincible Weapon. // Therefore let us sing to Christ our God, for He has been glorified.", "n": 7, "head": "Tone 8 Katavasia, Ode 1 (from the Canon of the Elevation of the Cross,"},
    {"k": "heading", "p": [344, 344], "text": "Tone 2 1st Canon, Ode 3 – Heirmos"},
    {"k": "text", "p": [346, 349], "text": "Establish us in Thyself, O Lord; | Thou Who on the Tree didst put sin to death, | and implant the fear of Thee in the hearts // of us who sing praises to Thee.", "n": 4, "head": "Tone 2 1st Canon, Ode 3 – Heirmos"},
    {"k": "heading", "p": [351, 351], "text": "Tone 8 Katavasia, Ode 3"},
    {"k": "text", "p": [353, 357], "text": "The rod of Aaron is an image of this mystery, | for when it budded it revealed who should be the priest; | and for the Church, which before was barren, | the Tree of the Cross has blossomed forth // for her strength and firm foundation.", "n": 5, "head": "Tone 8 Katavasia, Ode 3"},
    {"k": "note", "p": [359, 359], "text": "The Little Litany, then the Kathisma Hymns (not presented here)."},
    {"k": "heading", "p": [361, 361], "text": "Tone 2 1st Canon, Ode 4 – Heirmos"},
    {"k": "text", "p": [363, 365], "text": "I have heard, O Lord, the report of Thy dispensation, | and I have glorified Thee, // the only Lover of mankind.", "n": 3, "head": "Tone 2 1st Canon, Ode 4 – Heirmos"},
    {"k": "heading", "p": [367, 367], "text": "Tone 8 Katavasia, Ode 4"},
    {"k": "text", "p": [369, 371], "text": "I have heard the mystery of Thy dispensation, O Lord, | I have meditated on Thy works // and have glorified Thy Godhead.", "n": 3, "head": "Tone 8 Katavasia, Ode 4"},
    {"k": "heading", "p": [373, 373], "text": "Tone 2 1st Canon, Ode 5 – Heirmos"},
    {"k": "text", "p": [375, 378], "text": "Thou hast dispelled the mist of dark sayings obscurely worded, | and hast illumined the hearts of the faithful | by the fulfillment of the truth through the Maiden of God; // guide us also by Thy light, O Christ!", "n": 4, "head": "Tone 2 1st Canon, Ode 5 – Heirmos"},
    {"k": "heading", "p": [380, 380], "text": "Tone 8 Katavasia, Ode 5"},
    {"k": "text", "p": [382, 385], "text": "O thrice-blessed Tree, on which Christ the King and Lord was stretched! | Through thee the one who deceived us through a tree has fallen, | caught by the bait of God, Who was nailed to thee in the flesh, // and Who grants peace to our souls.", "n": 4, "head": "Tone 8 Katavasia, Ode 5"},
    {"k": "heading", "p": [387, 387], "text": "Tone 2 1st Canon, Ode 6 – Heirmos"},
    {"k": "text", "p": [389, 393], "text": "From within the belly of the whale Jonah cried to the Lord: | “Lead me up, I pray Thee, from the depths of hell, | that with a voice of praise | and in the Spirit of truth // I may sacrifice to Thee as my Deliverer!”", "n": 5, "head": "Tone 2 1st Canon, Ode 6 – Heirmos"},
    {"k": "heading", "p": [396, 396], "text": "Tone 8 Katavasia, Ode 6"},
    {"k": "text", "p": [398, 403], "text": "In the belly of the sea monster, Jonah stretched out his hands in the form of a cross, | plainly prefiguring the saving Passion. | When he emerged from there on the third day, | he prefigured the transcendent Resurrection of Christ our God, | Who was nailed to the Cross in the flesh // and by His rising on the third day enlightened the world.", "n": 6, "head": "Tone 8 Katavasia, Ode 6"},
    {"k": "note", "p": [405, 405], "text": "The Little Litany, then the Kontakion:"},
    {"k": "heading", "p": [407, 407], "text": "Tone 4 Kontakion"},
    {"k": "text", "p": [409, 413], "text": "By thy nativity, O most pure [Vir]gin, | Joachim and Anna are freed from [bar]renness, | Adam and Eve — from the cor[rup]tion of death. | And we, thy people, freed from the guilt of sin, celebrate and [sing] to thee: // “The barren woman gives birth to the Theotokos, the [nour]isher of our Life.”", "n": 5, "head": "Tone 4 Kontakion", "pointed": true},
    {"k": "heading", "p": [415, 415], "text": "Tone 2 1st Canon, Ode 7 – Heirmos"},
    {"k": "text", "p": [417, 423], "text": "The bush on the mountain unconsumed by fire | and the Chaldean furnace that shed dew | plainly prefigured thee, the Bride of God, | for thou didst receive, without being consumed, | the divine and immaterial Fire in a material womb. | Therefore, we cry to Him Who was born of thee: // “Blessed art Thou, the God of our Fathers!”", "n": 7, "head": "Tone 2 1st Canon, Ode 7 – Heirmos"},
    {"k": "heading", "p": [425, 425], "text": "Tone 8 Katavasia, Ode 7"},
    {"k": "text", "p": [427, 435], "text": "The senseless decree of the impious tyrant, | spewing threats and blasphemy hateful to God, | brought the people to confusion. | Yet the three Children could not be frightened | either by the brutal fury or the roaring fire, | but in the wind, moist with dew, that blew against it, | they stood together, and they sang: | “O praised above all, blessed art Thou, // our God, and the God of our Fathers!”", "n": 9, "head": "Tone 8 Katavasia, Ode 7"},
    {"k": "heading", "p": [436, 436], "text": "Tone 2 1st Canon, Ode 8 – Heirmos"},
    {"k": "text", "p": [438, 444], "text": "In the furnace of the Children, | once Thou didst prefigure Thine own Mother, O Lord; | and this type delivered them from the fire | as they walked in the midst of it unconsumed. | To her do we sing praises | as Thou hast manifested her today to the ends of the earth, // and we exalt her above all forever.", "n": 7, "head": "Tone 2 1st Canon, Ode 8 – Heirmos"},
    {"k": "heading", "p": [446, 446], "text": "Tone 8 Katavasia, Ode 8"},
    {"k": "text", "p": [448, 452], "text": "O Children, equal in number to the Trinity, | bless God the Father, the Creator; | praise the Word, Who descended and changed the fire to dew, | and exalt above all, to all ages, // the All-Holy Spirit, Who gives life to all!", "n": 5, "head": "Tone 8 Katavasia, Ode 8"},
    {"k": "note", "p": [454, 454], "text": "We praise, bless, and worship the Lord, singing and exalting Him throughout all ages."},
    {"k": "heading", "p": [456, 456], "text": "Tone 2 1st Canon, Ode 9 – Heirmos"},
    {"k": "text", "p": [458, 458], "text": "Magnify, O my soul, the most glorious birth of the Mother of God!", "n": 1, "head": "Tone 2 1st Canon, Ode 9 – Heirmos"},
    {"k": "text", "p": [460, 464], "text": "From thy virgin womb thou ineffably gavest a body | to the Light that was before the sun, | even God Who has shone forth upon us, | and in the body came to dwell among us. // Blessed and all-pure Theotokos, we magnify thee!", "n": 5, "head": "Tone 2 1st Canon, Ode 9 – Heirmos"},
    {"k": "heading", "p": [466, 466], "text": "Tone 8 Katavasia, Ode 9"},
    {"k": "text", "p": [468, 472], "text": "Thou art a mystical Paradise, O Theotokos, | who, though untilled, hast brought forth Christ; | through Him the life-bearing wood of the Cross was planted on earth. | Now at its Exaltation, | as we bow in worship before it, we magnify thee.", "n": 5, "head": "Tone 8 Katavasia, Ode 9"},
    {"k": "heading", "p": [475, 475], "text": "2nd Exapostilarion Tone 2"},
    {"k": "text", "p": [477, 480], "text": "Be renewed, O Adam, and be magnified, O Eve, | you prophets dance with the apostles and the righteous; | let there be common joy in the world among angels and mankind. // For the Theotokos is born today of righteous Joachim and Anna.", "n": 4, "head": "2nd Exapostilarion Tone 2"},
    {"k": "heading", "p": [482, 482], "text": "The Praises Tone 1"},
    {"k": "text", "p": [484, 487], "text": "Let [ev]erything that breathes [praise] the Lord! | Praise the Lord from the [heav]ens! | [Praise] Him in the [high]est! // To Thee, O God, is [due] a song!", "n": 4, "head": "The Praises Tone 1", "pointed": true},
    {"k": "text", "p": [489, 491], "text": "[Praise] Him, all you [An]gels of His! | Praise Him, [all] His hosts! // To Thee, O God, is [due] a song!", "n": 3, "head": "The Praises Tone 1", "pointed": true},
    {"k": "text", "p": [493, 493], "text": "V. Praise Him for His mighty deeds; praise Him according to His exceeding greatness! (Ps. 150:2)", "n": 1, "head": "The Praises Tone 1"},
    {"k": "heading", "p": [495, 495], "text": "Tone 1 [(Oh, the Marvelous Wonder)]"},
    {"k": "text", "p": [497, 504], "text": "[Oh], the marvelous [won]der! | The source of Life is born of a barren [wom]an, | and [grace] gloriously begins to [bear] its fruit. | Rejoice, Joachim, who have become the father of the [The]o[to]kos! | There is no [oth]er like thee among earthborn fathers, O man in[spired] by God; | for the Maiden in whom God would [come] to dwell, | the [Tab]ernacle of God, the all-holy [Moun]tain, // has been given to [us] through thee.", "n": 8, "head": "Tone 1 [(Oh, the Marvelous Wonder)]", "pointed": true},
    {"k": "text", "p": [506, 506], "text": "V. Praise Him with trumpet sound; praise Him with lute and harp! (Ps. 150:3)", "n": 1, "head": "Tone 1 [(Oh, the Marvelous Wonder)]"},
    {"k": "text", "p": [508, 508], "text": "(Repeat: “Oh, the marvelous wonder!…”)", "n": 1, "head": "Tone 1 [(Oh, the Marvelous Wonder)]"},
    {"k": "text", "p": [510, 510], "text": "V. Praise Him with timbrel and dance; praise Him with strings and pipe! (Ps. 150:4)", "n": 1, "head": "Tone 1 [(Oh, the Marvelous Wonder)]"},
    {"k": "text", "p": [513, 519], "text": "[Oh], the marvelous [won]der! | The fruit of a barren [wom]an | has shone [forth] at the behest of the Almighty [Mak]er of all | and mightily destroyed the barrenness of this world, which was [fruit]less in [good] things. | You [moth]ers, dance with the mother of the Theo[to]kos and cry: | “Rejoice, O Full of Grace, the Lord is [with] thee, // He Who grants the world through thee His great [mer]cy!”", "n": 7, "head": "Tone 1 [(Oh, the Marvelous Wonder)]", "pointed": true},
    {"k": "text", "p": [521, 521], "text": "V. Praise Him with sounding cymbals; praise Him with loud clashing cymbals! Let everything that breathes praise the Lord! (Ps. 150:5)", "n": 1, "head": "Tone 1 [(Oh, the Marvelous Wonder)]"},
    {"k": "text", "p": [523, 528], "text": "A living [pil]lar of [chas]tity | and bright vessel [shin]ing with grace, | glorious [An]na has given birth to the true stronghold of vir[gin]ity, | the divine flower, who manifestly bestows the [beau]ty of vir[gin]ity | on all [vir]gins and women who de[sire] that grace, // and grants to all the faithful great [mer]cy.", "n": 6, "head": "Tone 1 [(Oh, the Marvelous Wonder)]", "pointed": true},
    {"k": "note", "p": [530, 530], "text": "Glory to the Father, and to the Son, and to the Holy Spirit;"},
    {"k": "note", "p": [531, 531], "text": "now and ever, and unto ages of ages. Amen."},
    {"k": "heading", "p": [533, 533], "text": "Tone 6"},
    {"k": "text", "p": [535, 542], "text": "This is the [day] of the Lord! | Rejoice, O [peo]ples, | for, behold, the bridal chamber of the Light, the book of the [Word] of Life, | has come [forth] from the womb! | The gate that faces the [East] is born | and awaits the entry of the [Great] Priest. | She alone admits [Christ] into the world // for the sal[va]tion of our souls.", "n": 8, "head": "Tone 6", "pointed": true},
    {"k": "note", "p": [544, 544], "text": "The Great Doxology"},
    {"k": "heading", "p": [547, 547], "text": "Tone 4 Troparion"},
    {"k": "text", "p": [549, 555], "text": "Thy nativity, O [Vir]gin, | has proclaimed joy to the whole [u]niverse! | The Sun of righteousness, [Christ] our God, | has shone from thee, O Theo[to]kos. | By an[nul]ling the curse, | He bestowed a [bless]ing. // By destroying death, He has granted us e[ter]nal life.", "n": 7, "head": "Tone 4 Troparion", "pointed": true},
    {"k": "note", "p": [557, 557], "text": "Then the Augmented Litany, the Litany of Fervent Supplication, the Prayer of Inclination, and the Great Dismissal."},
    {"k": "heading", "p": [559, 559], "text": "(at the Divine Liturgy)"},
    {"k": "heading", "p": [561, 561], "text": "Tone 4 Troparion"},
    {"k": "text", "p": [563, 569], "text": "Thy nativity, O [Vir]gin, | has proclaimed joy to the whole [u]niverse! | The Sun of righteousness, [Christ] our God, | has shone from thee, O Theo[to]kos. | By an[nul]ling the curse, | He bestowed a [bless]ing. // By destroying death, He has granted us e[ter]nal life.", "n": 7, "head": "Tone 4 Troparion", "pointed": true},
    {"k": "heading", "p": [571, 571], "text": "Tone 4 Kontakion"},
    {"k": "text", "p": [573, 577], "text": "By thy nativity, O most pure [Vir]gin, | Joachim and Anna are freed from [bar]renness, | Adam and Eve — from the cor[rup]tion of death. | And we, thy people, freed from the guilt of sin, celebrate and [sing] to thee: // “The barren woman gives birth to the Theotokos, the [nour]isher of our Life.”", "n": 5, "head": "Tone 4 Kontakion", "pointed": true},
    {"k": "heading", "p": [579, 579], "text": "Tone 3 Prokeimenon (Song of the Theotokos)"},
    {"k": "text", "p": [581, 581], "text": "My soul doth magnify the Lord, / and my spirit hath rejoiced in God my Savior. (Lk. 1:46-47)", "n": 1, "head": "Tone 3 Prokeimenon (Song of the Theotokos)"},
    {"k": "text", "p": [583, 583], "text": "V. For He hath regarded the low estate of His handmaiden, for behold, all generations will call me blessed. (Lk. 1:48)", "n": 1, "head": "Tone 3 Prokeimenon (Song of the Theotokos)"},
    {"k": "heading", "p": [585, 585], "text": "Epistle"},
    {"k": "text", "p": [586, 586], "text": "(240) Philippians 2:5-11", "n": 1, "head": "Epistle"},
    {"k": "heading", "p": [588, 588], "text": "Tone 8"},
    {"k": "text", "p": [589, 589], "text": "Alleluia, Alleluia, Alleluia!", "n": 1, "head": "Tone 8"},
    {"k": "text", "p": [591, 591], "text": "V. Hearken, O daughter, and see, and incline thine ear! (Ps. 44:9a)", "n": 1, "head": "Tone 8"},
    {"k": "text", "p": [593, 593], "text": "V. Even the rich among the people shall pray before thy face. (Ps. 44:11b)", "n": 1, "head": "Tone 8"},
    {"k": "heading", "p": [595, 595], "text": "Gospel"},
    {"k": "text", "p": [596, 596], "text": "(54) Luke 10:38-42; 11:27-28", "n": 1, "head": "Gospel"},
    {"k": "heading", "p": [597, 597], "text": "(Instead of “It is truly meet…,” we sing:)"},
    {"k": "heading", "p": [599, 599], "text": "Tone 8"},
    {"k": "text", "p": [601, 601], "text": "Magnify, O my soul, the most glorious birth of the Mother of God!", "n": 1, "head": "Tone 8"},
    {"k": "text", "p": [603, 606], "text": "Virginity is foreign to mothers; | childbearing is strange for virgins. | But in thee, O Theotokos, both were accomplished. // For this all the earthly nations unceasingly magnify thee.", "n": 4, "head": "Tone 8"},
    {"k": "heading", "p": [608, 608], "text": "Communion Hymn"},
    {"k": "text", "p": [610, 611], "text": "I will receive the cup of salvation and call on the Name of the Lord. (Ps. 115:4) | Alleluia, Alleluia, Alleluia!", "n": 2, "head": "Communion Hymn"},
    {"k": "note", "p": [614, 614], "text": "© 2009 The Orthodox Church in America. Permission is granted to duplicate for liturgical use only. All other rights reserved."},
  ],
};
